<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver;

use Psr\Container\ContainerInterface;
use Override;
use Slim\Routing\RouteCollectorProxy;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetAllowController;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetListController;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetCreateController;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetRetrieveController;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetUpdateController;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetDeleteController;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetEnableController;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driver\Rest\TemplateSnippetDisableController;
use Civi\Lughauth\Shared\Security\Rbac\Handler;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Shared\Security\SecurityPlugin;
use Civi\Lughauth\Shared\Infrastructure\StartupProcessor;
use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Service\Visibility\TemplateSnippetRestrictFilterToVisibility;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Filter\TenantAccesible;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Fields\FixTenantExcludingRoot;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Service\Visibility\TemplateSnippetCollectNonEditableFields;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Allow\Create\IsAuthenticatedCreateAllow;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Create\TemplateSnippetCreateAllowDecision;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Allow\Update\IsAuthenticatedUpdateAllow;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Update\TemplateSnippetUpdateAllowDecision;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Allow\Retrieve\IsAuthenticatedRetrieveAllow;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Retrieve\TemplateSnippetRetrieveAllowDecision;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Allow\List\IsAuthenticatedListAllow;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\List\TemplateSnippetListAllowDecision;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Allow\Delete\IsAuthenticatedDeleteAllow;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Delete\TemplateSnippetDeleteAllowDecision;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Allow\Enable\IsAuthenticatedEnableAllow;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Enable\TemplateSnippetEnableAllowDecision;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Policy\Allow\Disable\IsAuthenticatedDisableAllow;
use Civi\Lughauth\Features\Document\TemplateSnippet\Application\Usecase\Disable\TemplateSnippetDisableAllowDecision;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driven\TemplateSnippetReadRepositoryAdapter;
use Civi\Lughauth\Features\Document\TemplateSnippet\Infrastructure\Driven\TemplateSnippetWriteRepositoryAdapter;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetReadGateway;
use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\Gateway\TemplateSnippetWriteGateway;

class TemplateSnippetPlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[TemplateSnippetReadGateway::class] = \DI\autowire(TemplateSnippetReadRepositoryAdapter::class);
        $def[TemplateSnippetWriteGateway::class] = \DI\autowire(TemplateSnippetWriteRepositoryAdapter::class);
        return $def;
    }
    #[Override]
    public function registerRoutes(RouteCollectorProxy $collector): void
    {
        $collector->group('/api/document/template-snippet', [$this, 'setRoutesForTemplateSnippet']);
        $collector->group('/api/me/acl/document/template-snippet', [$this, 'setRoutesForTemplateSnippetAcl']);
    }
    #[Override]
    public function registerEvents(EventListenersRegistrarInterface $listener): void
    {
        $listener->registerListener(TemplateSnippetRestrictFilterToVisibility::class, TenantAccesible::class);
        $listener->registerListener(TemplateSnippetCollectNonEditableFields::class, FixTenantExcludingRoot::class);
        $listener->registerListener(TemplateSnippetCreateAllowDecision::class, IsAuthenticatedCreateAllow::class);
        $listener->registerListener(TemplateSnippetUpdateAllowDecision::class, IsAuthenticatedUpdateAllow::class);
        $listener->registerListener(TemplateSnippetRetrieveAllowDecision::class, IsAuthenticatedRetrieveAllow::class);
        $listener->registerListener(TemplateSnippetListAllowDecision::class, IsAuthenticatedListAllow::class);
        $listener->registerListener(TemplateSnippetDeleteAllowDecision::class, IsAuthenticatedDeleteAllow::class);
        $listener->registerListener(TemplateSnippetEnableAllowDecision::class, IsAuthenticatedEnableAllow::class);
        $listener->registerListener(TemplateSnippetDisableAllowDecision::class, IsAuthenticatedDisableAllow::class);
    }
    #[Override]
    public function registerStartup(StartupProcessor $processor): void
    {
        $processor->register(function (ContainerInterface $container) {
            $handler = $container->get(Handler::class);
            $handler->registerResourceAction("template-snippet", "list", "READ");
            $handler->registerResourceAction("template-snippet", "create", "WRITE");
            $handler->registerResourceAction("template-snippet", "retrieve", "READ");
            $handler->registerResourceAction("template-snippet", "update", "WRITE");
            $handler->registerResourceAction("template-snippet", "delete", "WRITE");
            $handler->registerResourceAction("template-snippet", "enable", "WRITE");
            $handler->registerResourceAction("template-snippet", "disable", "WRITE");

            $handler->registerResourceAttribute("template-snippet", "code", "MANAGE");
            $handler->registerResourceAttribute("template-snippet", "tenant", "MANAGE");
            $handler->registerResourceAttribute("template-snippet", "contentHtml", "MANAGE");
            $handler->registerResourceAttribute("template-snippet", "enabled", "MANAGE");
            $handler->registerResourceAttribute("template-snippet", "version", "MANAGE");
        }, StartupProcessor::before(SecurityPlugin::STARTUP_ORDER));
    }
    public function setRoutesForTemplateSnippetAcl(RouteCollectorProxy $templateSnippetGroup): void
    {
        $templateSnippetGroup->get('', [TemplateSnippetAllowController::class, 'genericAllow']);
        $templateSnippetGroup->get('/{uid}', [TemplateSnippetAllowController::class, 'contextualAllow']);
    }
    public function setRoutesForTemplateSnippet(RouteCollectorProxy $templateSnippetGroup): void
    {
        $templateSnippetGroup->get('', [TemplateSnippetListController::class, 'list']);
        $templateSnippetGroup->post('', [TemplateSnippetCreateController::class, 'create']);
        $templateSnippetGroup->get('/{uid}', [TemplateSnippetRetrieveController::class, 'retrieve']);
        $templateSnippetGroup->put('/{uid}', [TemplateSnippetUpdateController::class, 'update']);
        $templateSnippetGroup->delete('/{uid}', [TemplateSnippetDeleteController::class, 'delete']);
        $templateSnippetGroup->delete('', [TemplateSnippetDeleteController::class, 'deleteAllForQuery']);
        $templateSnippetGroup->get('/~/delete-status/{uid}', [TemplateSnippetDeleteController::class, 'checkDeleteAllForQueryStatus']);
        $templateSnippetGroup->patch('/~/enable', [TemplateSnippetEnableController::class, 'enableAllForQuery']);
        $templateSnippetGroup->patch('/{uid}/enable', [TemplateSnippetEnableController::class, 'enable']);
        $templateSnippetGroup->get('/~/enable-status/{uid}', [TemplateSnippetEnableController::class, 'checkEnableAllForQueryStatus']);
        $templateSnippetGroup->patch('/~/disable', [TemplateSnippetDisableController::class, 'disableAllForQuery']);
        $templateSnippetGroup->patch('/{uid}/disable', [TemplateSnippetDisableController::class, 'disable']);
        $templateSnippetGroup->get('/~/disable-status/{uid}', [TemplateSnippetDisableController::class, 'checkDisableAllForQueryStatus']);
    }
}
